# Let me try a more precise approach by examining what characters map to what
# I'll create a mapping of all character transformations

inputs = ['jkeyhz', 'xyd', 'fhwbu', 'afcz', 'uahhhg']
outputs = ['jkeizhvz', 'xid', 'fzhvwbu', 'afcz', 'uaezhvg']

# Build character mapping
char_map = {}

for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            if inp[i] not in char_map:
                char_map[inp[i]] = outp[i]
            elif char_map[inp[i]] != outp[i]:
                # Multiple mappings for same input - this might be problematic
                print(f"Conflict: {inp[i]} maps to both {char_map[inp[i]]} and {outp[i]}")

print("Character mappings found:")
for k, v in char_map.items():
    print(f"  '{k}' -> '{v}'")

# Let me also check for additions
print("\nAdditions:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if len(outp) > len(inp):
        added = outp[len(inp):]
        print(f"  {inp} -> {outp} (added: '{added}')")
    elif len(inp) > len(outp):
        removed = inp[len(outp):]
        print(f"  {inp} -> {outp} (removed: '{removed}')")

